import json
source = """def settle(charges, slots):
    total = sum(charges.values())
    allocations = dict.fromkeys(charges, 0)
    if total == 0:
        return allocations
    remainders = {}
    for identifier, weight in charges.items():
        allocations[identifier], remainders[identifier] = divmod(slots * weight, total)
    remaining = slots - sum(allocations.values())
    for identifier in sorted(charges, key=lambda name: (-remainders[name], name))[:remaining]:
        allocations[identifier] += 1
    return allocations
"""
artifact = {
    "source": source,
    "result": {"zebra": 2, "gale": 2, "fern": 1, "iris": 0, "alder": 2},
    "edge": {"charges": {"z": 1, "a": 1}, "slots": 1, "expected": {"z": 0, "a": 1}}
}
