recovered = json.loads(payload)
ns = {}
exec(recovered["source"], ns)
settle = ns["settle"]
charges = {"zebra": 7, "gale": 5, "fern": 5, "iris": 0, "alder": 5}
original = charges.copy()
assert settle(charges, 7) == recovered["result"]
assert charges == original
