import json
source = """def settle(charges, slots):
    weights = {}
    caps = {}
    allocations = dict.fromkeys(charges, 0)
    for name, value in charges.items():
        if isinstance(value, int):
            weights[name] = value
            caps[name] = None
        else:
            weights[name] = value["weight"]
            caps[name] = value["cap"]
    remaining = slots
    while remaining > 0:
        eligible = [
            name for name in charges
            if weights[name] > 0
            and (caps[name] is None or allocations[name] < caps[name])
        ]
        if not eligible:
            break
        total = sum(weights[name] for name in eligible)
        proposals = {}
        remainders = {}
        for name in eligible:
            proposals[name], remainders[name] = divmod(
                remaining * weights[name], total
            )
        extra = remaining - sum(proposals.values())
        for name in sorted(eligible, key=lambda name: (-remainders[name], name))[:extra]:
            proposals[name] += 1
        for name in eligible:
            grant = proposals[name]
            if caps[name] is not None:
                grant = min(grant, caps[name] - allocations[name])
            allocations[name] += grant
            remaining -= grant
    return allocations
"""
artifact = {
    "source": source,
    "result": {"zebra": 1, "gale": 4, "fern": 2, "iris": 0, "alder": 4},
    "edge": {"charges": {"z": {"weight": 1, "cap": 1}, "a": 1}, "slots": 4, "expected": {"z": 1, "a": 3}}
}
payload = json.dumps(artifact)
decoded = json.loads(payload)
namespace = {}
exec(decoded["source"], namespace)
settle = namespace["settle"]
