def reference(charges, slots, first_only=False):
    weights = {k: v if isinstance(v, int) else v["weight"] for k, v in charges.items()}
    capacities = {k: slots if isinstance(v, int) else v["cap"] for k, v in charges.items()}
    out = dict.fromkeys(charges, 0)
    left = slots
    while left:
        active = [k for k in charges if weights[k] and out[k] < capacities[k]]
        if not active:
            break
        total = sum(weights[k] for k in active)
        quotas = {k: Fraction(left * weights[k], total) for k in active}
        proposal = {k: int(quotas[k]) for k in active}
        ranking = sorted(active, key=lambda k: (-(quotas[k] - proposal[k]), k))
        for k in ranking[:left - sum(proposal.values())]:
            proposal[k] += 1
        grants = {k: min(proposal[k], capacities[k] - out[k]) for k in active}
        for k, grant in grants.items():
            out[k] += grant
        left -= sum(grants.values())
        if first_only:
            break
    return out
